'use client'

import Link from 'next/link'
import { usePathname } from 'next/navigation'
import { ExternalLink, LayoutDashboard, LogOut, Megaphone, History, Users } from 'lucide-react'
import { logoutAdmin } from '@/app/admin/(protected)/actions'

const navItems = [
  { href: '/admin/inscriptions', label: 'Inscriptions', icon: Users },
  { href: '/admin/actualites', label: 'Actualités', icon: Megaphone },
  { href: '/admin/editions', label: 'Historique', icon: History },
]

function isActive(pathname: string, href: string) {
  return pathname === href || pathname.startsWith(`${href}/`)
}

export default function AdminHeader() {
  const pathname = usePathname()

  return (
    <header className="sticky top-0 z-40 border-b border-border/60 bg-background/95 backdrop-blur-md shadow-sm print:hidden">
      <div className="max-w-6xl mx-auto px-4 sm:px-6">
        <div className="flex items-center justify-between gap-3 py-3">
          <Link href="/admin/inscriptions" className="flex items-center gap-2.5 shrink-0 group">
            <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary text-primary-foreground shadow-sm">
              <LayoutDashboard className="h-4 w-4" />
            </div>
            <div className="hidden sm:block">
              <p className="text-sm font-bold text-foreground leading-tight group-hover:text-primary transition-colors">
                Mission Agapé
              </p>
              <p className="text-[0.65rem] text-muted-foreground uppercase tracking-wider">Administration</p>
            </div>
          </Link>

          <nav className="flex items-center gap-1 overflow-x-auto scrollbar-thin min-w-0" aria-label="Administration">
            {navItems.map((item) => {
              const active = isActive(pathname, item.href)
              const Icon = item.icon
              return (
                <Link
                  key={item.href}
                  href={item.href}
                  className={`inline-flex items-center gap-1.5 shrink-0 rounded-full px-3 py-1.5 text-xs sm:text-sm font-medium transition-all whitespace-nowrap ${
                    active
                      ? 'bg-primary text-primary-foreground shadow-sm shadow-primary/20'
                      : 'text-muted-foreground hover:text-foreground hover:bg-muted/70'
                  }`}
                >
                  <Icon className="w-3.5 h-3.5 shrink-0" />
                  {item.label}
                </Link>
              )
            })}
          </nav>

          <div className="flex items-center gap-1.5 sm:gap-2 shrink-0">
            <Link
              href="/"
              target="_blank"
              className="hidden md:inline-flex items-center gap-1.5 rounded-full border border-border px-3 py-1.5 text-xs font-medium text-muted-foreground hover:text-foreground hover:bg-muted/50 transition-colors"
            >
              <ExternalLink className="w-3.5 h-3.5" />
              Voir le site
            </Link>
            <form action={logoutAdmin}>
              <button
                type="submit"
                className="inline-flex items-center gap-1.5 rounded-full border border-border px-3 py-1.5 text-xs sm:text-sm font-medium text-muted-foreground hover:text-destructive hover:border-destructive/30 hover:bg-destructive/5 transition-colors"
              >
                <LogOut className="w-3.5 h-3.5 shrink-0" />
                <span className="hidden sm:inline">Déconnexion</span>
              </button>
            </form>
          </div>
        </div>
      </div>
    </header>
  )
}
